const long elen = scan_int("NDS_ELEN");
const long xlen = scan_int("NDS_XLEN");
// Hart-0 local memories, reported in BYTES (the config macro is KB). The
// descriptor's sizes mean "LM content TRANSPORT supported at this size":
// the driver passes --ilm/--dlm whenever they are > 0 and expects the exit
// sidecars back, so an engine must implement the FULL backdoor pair (load
// for resume AND dump for the exit drain -- the kCpuCan* authorities in
// simulator.hpp) to advertise; 0 = no memory or no backdoor (e.g.
// ax46mpv_advanced today: config has the memories, wrapper has no
// set_/get_), and the driver arms nothing.
using CPU = VSIM_CPU_INTERFACE_CLASS;
const long ilm_size = kCpuCanLoadIlm<CPU> && kCpuCanDumpIlm<CPU>
                        ? scan_int("NDS_ILM_SIZE_KB") * 1024 : 0;
const long dlm_size = kCpuCanLoadDlm<CPU> && kCpuCanDumpDlm<CPU>
                        ? scan_int("NDS_DLM_SIZE_KB") * 1024 : 0;
// Cluster-level HVM, same transport contract (--hvm in, .hvm sidecar out).
const long hvm_size = kCpuCanLoadHvm<CPU> && kCpuCanDumpHvm<CPU>
                        ? scan_int("NDS_HVM_SIZE_KB") * 1024 : 0;

// Built by hand (not fmt) to keep the literal {bin}/{elf}/{state_in}
// placeholders out of fmt's brace parser.
std::string json;
json += "{\n";
json += "  \"id\": \"verilator:" + cfg + "\",\n";
json += "  \"type\": \"verilator\",\n";
json += "  \"kind\": \"cycle-accurate\",\n";
json += "  \"vlen\": " + std::to_string(vlen) + ", \"dlen\": "
        + std::to_string(dlen) + ", \"elen\": " + std::to_string(elen)
        + ", \"xlen\": " + std::to_string(xlen) + ",\n";
json += "  \"ilm_size\": " + std::to_string(ilm_size) + ", \"dlm_size\": "
        + std::to_string(dlm_size) + ", \"hvm_size\": "
        + std::to_string(hvm_size) + ",\n";
json += "  \"triggers\": [\"csr\", \"pc\"],\n";
json += "  \"roles\": [\"standalone\", \"accurate-leg\"],\n";
json += "  \"state\": [\"resume\", \"drain\"],\n";

