// HVM bank backdoor copy (HVM transport F1, ROADMAP_hvm): rows are wide
// Verilated words (VlWide<16> -- 16 independent 32-bit data lanes per row,
// no ECC/parity), a geometry lm_backdoor_read's one-word-per-row decode
// below cannot express, hence the separate pair. Lane k of a row holds
// bytes 4k..4k+3, little-endian (R2, pinned by the head/tail probes of
// tests/vsim/test_vsim_hvm_load.sh). `base` is the bank's byte offset into
// the image; the write zero-fills where the image does not reach. The two
// duals share the geometry so the byte order cannot drift.
void hvm_bank_write(auto& mem, size_t bank_bytes,
                    const std::vector<uint8_t>& data, size_t base)
{
  constexpr size_t lanes = sizeof(mem[0]) / sizeof(mem[0][0]);
  for (size_t row = 0; row < bank_bytes / (lanes * 4); ++row)
    for (size_t lane = 0; lane < lanes; ++lane) {
      uint32_t w = 0;
      for (size_t j = 0; j < 4; ++j) {
        const size_t idx = base + row * lanes * 4 + lane * 4 + j;
        if (idx < data.size())
          w |= static_cast<uint32_t>(data[idx]) << (j * 8);
      }
      mem[row][lane] = w;
    }
}

void hvm_bank_read(auto& mem, size_t bank_bytes, uint8_t* out)
{
  constexpr size_t lanes = sizeof(mem[0]) / sizeof(mem[0][0]);
  for (size_t row = 0; row < bank_bytes / (lanes * 4); ++row)
    for (size_t lane = 0; lane < lanes; ++lane) {
      const uint32_t w = mem[row][lane];
      for (size_t j = 0; j < 4; ++j)
        out[row * lanes * 4 + lane * 4 + j] = static_cast<uint8_t>(w >> (j * 8));
    }
}

